#!/usr/bin/bash

set -eoux pipefail

source /ctx/build/repo-helpers.sh

systemctl disable rpm-ostreed-automatic.timer
systemctl mask flatpak-add-fedora-repos.service
systemctl disable rpm-ostree-countme.timer
systemctl mask rpm-ostree-countme.timer rpm-ostree-countme.service
systemctl disable sshd.service sshd.socket
# Generated by systemd-ssh-generator; also off via systemd.ssh_auto=no karg
systemctl mask sshd-unix-local.socket sshd-vsock.socket
systemctl disable systemd-homed.service systemd-homed-activate.service
systemctl disable iscsid.socket iscsiuio.socket iscsi-starter.service iscsi-onboot.service
systemctl disable sssd.service
systemctl disable sssd-kcm.socket sssd-kcm.service
systemctl mask sssd-kcm.socket sssd-kcm.service
systemctl disable nfs-client.target
systemctl disable uresourced.service
systemctl mask uresourced.service
systemctl --global mask uresourced.service

# Disable repos inherited from base image
for repo in /etc/yum.repos.d/_copr*.repo; do
	[[ -f "$repo" ]] && repo_disable "$repo"
done

dnf5 clean all

# Keep unchanged rebuilds byte-identical so clients reuse rechunked layers:
# dnf5 history records install times, and font caches embed directory mtimes
# (ostree zeroes them at deploy time anyway)
rm -f /usr/lib/sysimage/libdnf5/transaction_history.sqlite*
for dir in /usr/share/fonts /usr/share/X11/fonts; do
	[[ -d "$dir" ]] && find "$dir" -type d -exec touch -h -d @0 {} +
done
fc-cache -sf

# shellcheck disable=SC2114
rm -rf /boot && mkdir -p /boot
rm -rf /tmp && mkdir -p /tmp
rm -rf /run && mkdir -p /run
# shellcheck disable=SC2115
rm -rf /var/* && mkdir /var/tmp

# Validate no repos are left enabled (Fedora 45 moves Fedora repos to /usr/share/dnf5/repos.d)
VALIDATION_FAILED=0

for repo in /etc/yum.repos.d/*.repo /usr/share/dnf5/repos.d/*.repo; do
	[[ -f "$repo" ]] || continue
	basename_repo=$(basename "$repo")
	[[ "$basename_repo" == fedora.repo ]] && continue
	[[ "$basename_repo" == fedora-rawhide.repo ]] && continue
	[[ "$basename_repo" == fedora-updates*.repo ]] && continue
	[[ "$basename_repo" == fedora-cisco-openh264.repo ]] && continue
	if is_repo_enabled "$repo"; then
		echo "ERROR: Enabled repo found: $repo"
		grep -iE -B5 "$REPO_ENABLED_RE" "$repo"
		VALIDATION_FAILED=1
	fi
done

if [[ $VALIDATION_FAILED -eq 1 ]]; then
	echo "Build failed: third-party repos left enabled"
	exit 1
fi

# Symlink /usr/local and /opt to /var so they are writable on bootc. Keep the
# targets relative like the base image: bootc's runtime-deps lint resolves $PATH
# inside the rootfs and rejects absolute symlinks as escaping it.
# shellcheck disable=SC2114
rm -rfv /opt /usr/local
ln -s ../var/usrlocal /usr/local
ln -s var/opt /opt
